// Surface coverage inferred from the unchanged owner-supplied reference image.
// RGB channels: sand, visible snow, canopy. Illustration markers excluded.
const d=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
export function referenceSurface(x,z){const u=Math.max(0,Math.min(511.999,(x/12600+.5)*512)),v=Math.max(0,Math.min(341.999,(z/8400+.5)*342)),a=Math.floor(u),b=Math.floor(v),fx=u-a,fz=v-b,i=(b*513+a)*3;function f(k){return ((d[i+k]*(1-fx)+d[i+3+k]*fx)*(1-fz)+(d[i+1539+k]*(1-fx)+d[i+1542+k]*fx)*fz)/255;}return {sand:f(0),snow:f(1),canopy:f(2)};}
